-- Lösungswege für die Forderungskarte (ohne Punkte). Upsert, damit gespeicherte Forderungen ihren Verweis behalten.
insert into public.instrumente (id, thema_id, name, begruendung, evidenz, beleg_studie_url, ebene, entspricht, ki_entwurf, entwurf_herkunft) values
  (6099, 6, 'Asylsuchende an den Binnengrenzen zurückweisen', 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'gemischt', null, 'bund', null, true, null),
  (6100, 6, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen', 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'gemischt', null, 'bund', null, true, null),
  (6101, 6, 'Anerkennung ausländischer Berufsabschlüsse vereinfachen', 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'gemischt', null, 'bund', null, true, null),
  (6102, 6, 'Arbeit parallel zum Sprachkurs (Job-Turbo)', 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'gemischt', null, 'bund', null, true, null),
  (6103, 6, 'Mehr Staaten als sichere Herkunftsstaaten einstufen', 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'gemischt', null, 'bund', null, true, null),
  (6104, 6, 'Rücknahme- und Migrationsabkommen mit Herkunftsstaaten', 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'gemischt', null, 'bund', null, true, null),
  (6105, 6, 'Mehr Abschiebungshaft und Ausreisegewahrsam', 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6106, 6, 'Asylverfahren in Drittstaaten außerhalb der EU', 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'offen', null, 'bund', null, true, null),
  (6107, 6, 'Integrations- und Sprachkurse ausbauen', 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'belegt', null, 'bund', null, true, null),
  (6108, 6, 'Bleiberecht für gut integrierte Geduldete (Spurwechsel)', 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'belegt', null, 'bund', null, true, null),
  (6109, 6, 'Verbindliche Verteilung Schutzsuchender in der EU', 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'offen', null, 'bund', null, true, null),
  (6110, 6, 'Arbeitsverbote für Geflüchtete abschaffen', 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'belegt', null, 'bund', null, true, null),
  (6111, 6, 'Straftäter vorrangig abschieben', 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'gemischt', null, 'bund', null, true, null),
  (6112, 6, 'Mehr Personal für Asylbehörden und Verwaltungsgerichte', 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'gemischt', null, 'bund', null, true, null),
  (6113, 6, 'Bezahlkarte oder Sachleistungen für Asylsuchende (Land)', 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'offen', null, 'land', null, true, null),
  (6114, 6, 'Asylsuchende zentral in Landes- oder Großunterkünften unterbringen (Land)', 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'offen', null, 'land', null, true, null),
  (6115, 6, 'Ausländerbehörden personell und digital stärken (Land)', 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'offen', null, 'land', null, true, null),
  (6116, 6, 'Kommunen und Bezirke für die Aufnahme finanziell stärker ausstatten (Land)', 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'gemischt', null, 'land', null, true, null),
  (6117, 6, 'Auf Bundes- und EU-Ebene auf weniger Zugang dringen (Land)', 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'gemischt', null, 'land', null, true, null),
  (6118, 6, 'Geflüchtete dezentral in Wohnungen unterbringen (Land)', 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'gemischt', null, 'land', null, true, null),
  (6119, 6, 'Verteilung im Land an der Aufnahmefähigkeit der Kommunen ausrichten (Land)', 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'gemischt', null, 'land', null, true, null),
  (6120, 6, 'Aufnahmestopp des Landes', 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'offen', null, 'land', null, true, null),
  (6121, 6, 'Mehr Unterbringungsplätze verbindlich schaffen (Land)', 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'gemischt', null, 'land', null, true, null),
  (6122, 6, 'Vom Bund die volle Übernahme der Unterbringungskosten fordern (Land)', 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'gemischt', null, 'land', null, true, null)
on conflict (id) do update set thema_id = excluded.thema_id, name = excluded.name, begruendung = excluded.begruendung,
  evidenz = excluded.evidenz, beleg_studie_url = excluded.beleg_studie_url, ebene = excluded.ebene,
  entspricht = excluded.entspricht, ki_entwurf = excluded.ki_entwurf, entwurf_herkunft = excluded.entwurf_herkunft;

delete from public.instrumente where thema_id = 6 and id not in (6099, 6100, 6101, 6102, 6103, 6104, 6105, 6106, 6107, 6108, 6109, 6110, 6111, 6112, 6113, 6114, 6115, 6116, 6117, 6118, 6119, 6120, 6121, 6122);

insert into public.massnahmen (id, thema_id, partei_id, land, beschreibung, ursachen_ids, instrument_id, wirksamkeit, umsetzbarkeit,
  rollen_modifikator, begruendung, beleg_programm_url, beleg_studie_url, evidenz, stand, geprueft, ki_entwurf, entwurf_herkunft) values
  (6001, 6, 11, null, 'Asylsuchende an den deutschen Grenzen zurückweisen, wenn sie aus einem EU- oder Schengen-Staat einreisen', '{601,605}', 6099, 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=42', null, 'gemischt', '2026-09-29', false, true, null),
  (6002, 6, 11, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, freiwillige Aufnahmeprogramme beenden', '{601}', 6100, 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6003, 6, 11, null, 'Berufsanerkennung vereinfachen, Deutschlernen „on the job“ stärken', '{603}', 6101, 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6004, 6, 11, null, 'Arbeitsvermittlung nicht wegen laufender Sprach- oder Integrationskurse aufschieben; Spracherwerb berufsbegleitend', '{603}', 6102, 2, 3, null, 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=31', null, 'gemischt', '2026-09-29', false, true, null),
  (6005, 6, 11, null, 'Weitere Länder als sichere Herkunftsstaaten einstufen', '{602}', 6103, 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6006, 6, 11, null, 'Mehr Rücknahmeabkommen mit den Hauptherkunftsländern', '{604,606}', 6104, 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6007, 6, 11, null, 'Unterstützung des Bundes für die Länder bei Reisepapieren und Rückführungen ausbauen', '{604,606}', null, 2, 3, null, 'Fehlende Reisepapiere sind ein Haupthindernis für Abschiebungen und ein häufiger Grund für lange Duldungen. Der Bund hilft den Ländern dabei schon heute und kann das ausbauen; ob die Herkunftsstaaten Papiere ausstellen, bleibt aber offen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6008, 6, 11, null, 'Zentrale Asylverfahren für beschleunigte Verfahren und Bundesausreisezentren', '{602,604}', null, 1, 2, null, 'Zentrale Einrichtungen können Verfahren und Rückführungen bündeln; ob sie schneller sind, ist nicht untersucht, und an fehlenden Papieren ändern sie nichts. Der Bund müsste die Einrichtungen mit den Ländern aufbauen.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'offen', '2026-09-29', false, true, null),
  (6009, 6, 11, null, 'Bundespolizei darf Ausreisepflichtige in Haft oder Ausreisegewahrsam nehmen', '{604}', 6105, 1, 2, null, 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=43', null, 'gemischt', '2026-09-29', false, true, null),
  (6010, 6, 11, null, 'Asylverfahren in sicheren Drittstaaten außerhalb Europas', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.cdu.de/app/uploads/2025/01/km_btw_2025_wahlprogramm_langfassung_ansicht.pdf#page=44', null, 'offen', '2026-09-29', false, true, null),
  (6011, 6, 12, null, 'Asylverfahren beim Bundesamt und an den Verwaltungsgerichten durch Digitalisierung beschleunigen, Entscheidung in sechs Monaten', '{602}', null, 2, 2, null, 'Digitalisierung und Verwaltungsmodernisierung setzen an der Verfahrensdauer an; wie viel sie bringen, hängt von der Umsetzung ab. Das Bundesamt steuert der Bund, die Verwaltungsgerichte die Länder.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (6012, 6, 12, null, 'Ausländerbehörden stärken, Datenaustausch verbessern, Verfahren aus einer Hand', '{601}', null, 1, 2, null, 'Setzt an der Überlastung der Ausländerbehörden an, nennt aber weder Umfang noch Finanzierung. Die Behörden gehören zu Ländern und Kommunen, der Bund kann Datenaustausch und Digitalisierung beisteuern.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'gemischt', '2026-09-29', false, true, null),
  (6013, 6, 12, null, 'Integrationskurse ausbauen und ausreichend finanzieren', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'belegt', '2026-09-29', false, true, null),
  (6014, 6, 12, null, 'Spurwechsel in die Fachkräfteeinwanderung für integrierte, straffreie Menschen ohne Schutzstatus', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=54', null, 'belegt', '2026-09-29', false, true, null),
  (6015, 6, 12, null, 'Migrationsabkommen mit festen Vereinbarungen zur Rückführung Ausreisepflichtiger', '{604,606}', 6104, 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=56', null, 'gemischt', '2026-09-29', false, true, null),
  (6016, 6, 12, null, 'Solidarische Verteilung von Schutzsuchenden unter allen EU-Staaten', '{605}', 6109, 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://www.spd.de/fileadmin/Dokumente/Beschluesse/Programm/2025_SPD_Regierungsprogramm.pdf#page=55', null, 'offen', '2026-09-29', false, true, null),
  (6021, 6, 13, null, 'Kommunen mit einer Integrationsoffensive stärker und verlässlicher finanziell unterstützen', '{601}', null, 1, 2, null, 'Mehr Geld für die Kommunen setzt an der Kapazitätsseite an; das Programm nennt aber weder Umfang noch Weg der Finanzierung. Der Bund beteiligt sich bereits an den Kosten und kann mehr beisteuern.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'gemischt', '2026-09-29', false, true, null),
  (6022, 6, 13, null, 'Ausfinanzierte Integrations- und Sprachkurse direkt nach der Ankunft', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'belegt', '2026-09-29', false, true, null),
  (6023, 6, 13, null, 'Arbeitsverbote abschaffen; arbeitsbezogene Genehmigungen gelten nach kurzer Frist als erteilt', '{603}', 6110, 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=128', null, 'belegt', '2026-09-29', false, true, null),
  (6024, 6, 13, null, 'Spurwechsel ausgestalten; auf das Chancen-Aufenthaltsrecht weitere Reformen folgen lassen', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=127', null, 'belegt', '2026-09-29', false, true, null),
  (6025, 6, 13, null, 'Migrationsabkommen: geregelte Migrationswege, dafür nehmen Partnerländer Ausreisepflichtige zurück', '{604,606}', 6104, 2, 2, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind je nach Partnerland gemischt. Umsetzbar nur mit Zustimmung der Partnerstaaten.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=131', null, 'gemischt', '2026-09-29', false, true, null),
  (6026, 6, 13, null, 'Ausreisepflichtige nach schweren Straftaten vorrangig zurückführen', '{604}', 6111, 1, 2, null, 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'gemischt', '2026-09-29', false, true, null),
  (6027, 6, 13, null, 'Faire, verbindliche und solidarische Verteilung von Schutzsuchenden in Europa', '{605}', 6109, 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://cms.gruene.de/uploads/assets/20250318_Regierungsprogramm_DIGITAL_DINA5.pdf#page=130', null, 'offen', '2026-09-29', false, true, null),
  (6031, 6, 14, null, 'Zuständigkeit für Abschiebungen beim Bund zentralisieren', '{604}', null, 1, 1, null, 'Setzt an Vollzugsproblemen in den Ländern an; die Haupthindernisse (fehlende Papiere, Herkunftsstaaten) bleiben. Eine Bundeszuständigkeit für den Vollzug müsste neu geschaffen werden, mit Zustimmung des Bundesrats und je nach Ausgestaltung einer Grundgesetzänderung.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-29', false, true, null),
  (6032, 6, 14, null, 'Asylverfahren auch in Drittstaaten', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-09-29', false, true, null),
  (6033, 6, 14, null, 'Geordnetes Verfahren, um mehr sichere Herkunftsstaaten festzustellen', '{602}', 6103, 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6034, 6, 14, null, 'Familiennachzug zu subsidiär Schutzberechtigten aussetzen, Aufnahmeprogramme pausieren', '{601}', 6100, 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6035, 6, 14, null, 'Zurückweisungen an den deutschen Grenzen modellhaft erproben', '{601,605}', 6099, 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6036, 6, 14, null, 'EU-Migrationsabkommen für mehr Rücknahmebereitschaft; bilaterale Migrationspartnerschaften', '{604,606}', null, 2, 1, null, 'Abkommen mit Herkunftsstaaten setzen an den Haupthindernissen an (fehlende Papiere, fehlende Mitwirkung), die Abschiebungen verhindern und Duldungen verlängern; die Erfahrungen sind gemischt. Der Schwerpunkt liegt auf EU-Abkommen, die Deutschland nicht allein schließen kann.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6037, 6, 14, null, 'Spurwechsel für gut integrierte Schutzsuchende, die ohne Transferleistungen leben können', '{606}', null, 1, 3, null, 'Ein Spurwechsel beendet die Duldung für die, die ihn schaffen; die Bedingung, dass die ganze Familie ohne Transferleistungen lebt, erfüllen aber nur wenige Geduldete. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6038, 6, 14, null, 'Anerkennung ausländischer Abschlüsse beschleunigen und durchgehend digitalisieren', '{603}', 6101, 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=9', null, 'gemischt', '2026-09-29', false, true, null),
  (6039, 6, 14, null, 'Sprach- und Integrationskurse trennen; Sprachkurse modular und leistungsdifferenziert', '{603}', null, 1, 3, null, 'Modulare, berufsbegleitende Kurse können den Einstieg in Arbeit erleichtern; dass eine Trennung von Sprach- und Integrationskurs schneller zum Ziel führt, ist nicht untersucht. Die Kurse regelt der Bund.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=29', null, 'offen', '2026-09-29', false, true, null),
  (6040, 6, 14, null, 'Wohnsitzauflage stärker nutzen', '{601}', null, 1, 3, null, 'Die Wohnsitzauflage verteilt Geflüchtete gleichmäßiger auf die Kommunen und kann Ballungsräume entlasten; Studien finden aber, dass sie die Aufnahme von Arbeit verzögern kann. Per Bundesgesetz umsetzbar.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'gemischt', '2026-09-29', false, true, null),
  (6041, 6, 15, null, 'Grenzen selbst kontrollieren, illegal Einreisende an der Grenze zurückweisen', '{601,605}', 6099, 1, 1, null, 'Zurückweisungen an den Binnengrenzen können einzelne Einreisen verhindern; seit Mai 2025 betrafen sie nur einige hundert Asylsuchende, eine Wirkung auf die Zugangszahlen ist nicht belegt. Die Vereinbarkeit mit der Dublin-Verordnung ist umstritten (VG Berlin, Juni 2025: im Einzelfall rechtswidrig).', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'gemischt', '2026-09-29', false, true, null),
  (6042, 6, 15, null, 'Asylanträge künftig außerhalb Deutschlands stellen und bearbeiten', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'offen', '2026-09-29', false, true, null),
  (6043, 6, 15, null, 'Zahl der sicheren Herkunftsstaaten deutlich ausweiten', '{602}', 6103, 1, 2, null, 'Mehr sichere Herkunftsstaaten beschleunigen die Verfahren für Antragsteller aus diesen Ländern; die Hauptherkunftsländer (Syrien, Afghanistan, Türkei) kommen dafür aber kaum in Frage. Einstufung per Gesetz, beim Asylgrundrecht mit Zustimmung des Bundesrats.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'gemischt', '2026-09-29', false, true, null),
  (6044, 6, 15, null, 'Asylverfahren vor den Verwaltungsgerichten straffen, mehr Personal zum Abbau von Altfällen', '{602}', 6112, 2, 2, null, 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'gemischt', '2026-09-29', false, true, null),
  (6045, 6, 15, null, 'Druck auf nicht rücknahmebereite Herkunftsländer über Wirtschaftssanktionen, Entwicklungshilfe und Visa', '{604,606}', null, 2, 1, null, 'Druck auf Herkunftsstaaten setzt an deren fehlender Mitwirkung an, einem Haupthindernis für Abschiebungen; die Erfahrungen damit sind gemischt. Wirtschaftssanktionen und der Visahebel liegen bei der EU, nur die Entwicklungshilfe kann Deutschland allein kürzen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=108', null, 'gemischt', '2026-09-29', false, true, null),
  (6046, 6, 15, null, 'Haft- und Gewahrsamsplätze in Grenznähe und an Flughäfen ausbauen', '{604}', 6105, 1, 2, null, 'Mehr Haft und Gewahrsam kann verhindern, dass Ausreisepflichtige vor dem Termin untertauchen; die meisten Abschiebungen scheitern aber an fehlenden Papieren oder am Herkunftsstaat. Haft ist verfassungsrechtlich eng begrenzt, Haftplätze stellen überwiegend die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=108', null, 'gemischt', '2026-09-29', false, true, null),
  (6047, 6, 15, null, 'Grundsätzlichen Anspruch auf Familiennachzug zu subsidiär Schutzberechtigten streichen', '{601}', 6100, 1, 3, null, 'Das Aussetzen des Familiennachzugs zu subsidiär Schutzberechtigten senkt die Zahl der Neuankommenden etwas (vorher bis zu 1.000 Visa im Monat), im Verhältnis zu allen Zuzügen aber wenig; an den Kapazitäten vor Ort ändert es nichts. Per Bundesgesetz umsetzbar, 2025 für zwei Jahre beschlossen.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'gemischt', '2026-09-29', false, true, null),
  (6048, 6, 15, null, 'Asylsuchende für die Dauer des Verfahrens in zentralen Aufnahmeeinrichtungen unterbringen', '{601}', null, 1, 2, null, 'Entlastet die Kommunen bei der Unterbringung, verlagert die Last aber auf die Erstaufnahme der Länder; ob die Plätze reichen, ist offen. Die Wohnpflicht regelt der Bund, die Plätze schaffen die Länder.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=106', null, 'offen', '2026-09-29', false, true, null),
  (6049, 6, 15, null, 'Bundesprogramme zur Förderung der freiwilligen Rückkehr ausweiten', '{604,606}', null, 1, 3, null, 'Rückkehrförderung kann Ausreisen erleichtern, auch bei fehlenden Papieren; Studien finden eher begrenzte Effekte. Der Bund finanziert solche Programme bereits.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=109', null, 'gemischt', '2026-09-29', false, true, null),
  (6050, 6, 15, null, 'Pflicht zum Spracherwerb auf B2-Niveau in der Regel binnen zwei Jahren; Kosten abgebrochener Kurse erstatten', '{603}', null, 1, 2, null, 'Pflichten und Rückforderungen können den Abschluss von Kursen fördern, verkürzen aber keine Wartezeiten auf Kursplätze; eine Wirkung ist nicht untersucht. Per Bundesgesetz umsetzbar, Rückforderungen sind verwaltungsaufwendig.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=110', null, 'offen', '2026-09-29', false, true, null),
  (6051, 6, 16, null, 'Fonds für Willkommenskommunen; der Bund erstattet die Unterbringungskosten vollständig pro Person', '{601}', null, 2, 2, null, 'Mehr Bundesgeld setzt an der Kapazitätsseite an, vor allem bei der Unterbringung; Geld allein schafft aber nicht sofort Wohnraum und Personal. Der Bund beteiligt sich bereits mit einer Pauschale, eine volle Erstattung wäre deutlich teurer, die Finanzierung ist offen.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (6052, 6, 16, null, 'Uneingeschränkte Arbeitserlaubnis für alle Geflüchteten ab dem Tag der Ankunft', '{603}', 6110, 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'belegt', '2026-09-29', false, true, null),
  (6053, 6, 16, null, 'Flächendeckend kostenlose Sprachkurse für Geflüchtete', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=52', null, 'belegt', '2026-09-29', false, true, null),
  (6054, 6, 16, null, 'Legalisierung für Menschen ohne Aufenthaltsstatus; wirksame Bleiberechtsregelungen bei Kettenduldungen', '{606}', null, 2, 3, null, 'Bleiberechtsregelungen beenden lange Duldungen direkt; das Chancen-Aufenthaltsrecht von 2022 zeigt, dass solche Regelungen genutzt werden. Wer genau ein Bleiberecht bekommen soll, lässt das Programm offen. Per Bundesgesetz umsetzbar.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'belegt', '2026-09-29', false, true, null),
  (6055, 6, 16, null, 'Europäische Fluchtumlage: EU-Geld für aufnahmebereite Länder, Regionen und Städte', '{605}', null, 1, 1, null, 'Geld aus EU-Mitteln für aufnahmebereite Regionen könnte die Verteilung freiwillig verbessern; an den gescheiterten Überstellungen setzt es nur indirekt an. Umsetzbar nur mit einem Beschluss auf EU-Ebene.', 'https://www.die-linke.de/fileadmin/user_upload/Wahlprogramm_Langfassung_Linke-BTW25_01.pdf#page=53', null, 'offen', '2026-09-29', false, true, null),
  (6061, 6, 17, null, 'Job-Turbo für Ukrainer und andere Geflüchtete mit Schutzstatus umsetzen', '{603}', 6102, 2, 3, null, 'Arbeit parallel zum Sprachkurs kann den Einstieg beschleunigen; Studien zeigen, dass frühe Beschäftigung die Integration fördert, die Wirkung des Job-Turbos von 2023 ist aber noch nicht abschließend untersucht. Umsetzbar über die Bundesagentur für Arbeit.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true, null),
  (6062, 6, 17, null, 'Wer aus einem sicheren Drittstaat einreist, bekommt kein Asylverfahren und keinen Aufenthalt', '{601,605}', null, 1, 0, null, 'Würde Einreisen über Nachbarstaaten praktisch ausschließen, wenn diese die Menschen zurücknehmen. Die Dublin-Verordnung und das neue europäische Asylsystem verlangen aber eine Prüfung, welcher Staat zuständig ist; ein genereller Ausschluss ist mit dem EU-Recht nicht vereinbar.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=36', null, 'gemischt', '2026-09-29', false, true, null),
  (6063, 6, 17, null, 'Behörden und Gerichte vorrangig mit Personal ausstatten, Asylverfahren in drei Monaten', '{602}', 6112, 2, 2, null, 'Mehr Personal und gestraffte Verfahren setzen direkt an der Verfahrensdauer an; beim Bundesamt hat Personalaufbau Rückstände schon abgebaut. Das Bundesamt und das Asylprozessrecht regelt der Bund, das Personal der Verwaltungsgerichte stellen die Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (6064, 6, 17, null, 'Straftäter ausweisen und abschieben, Verfahren dazu vorrangig betreiben', '{604}', 6111, 1, 2, null, 'Vorrang für Straftäter setzt Schwerpunkte beim Vollzug, beseitigt aber nicht die Hindernisse (fehlende Papiere, Herkunftsstaaten), an denen Abschiebungen meist scheitern. Den Vollzug steuern die Ausländerbehörden der Länder.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (6065, 6, 17, null, 'Erwachsenenbildung zum Nachholen von Schulabschlüssen und Nachqualifikation bei abweichenden Berufsausbildungen', '{603}', null, 2, 2, null, 'Nachqualifizierung setzt an einer Hürde an, die das IAB nennt (Abschlüsse passen nicht zum deutschen System); Studien zeigen positive Effekte. Erwachsenenbildung ist weitgehend Ländersache, der Bund kann über die Arbeitsförderung beitragen.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=37', null, 'gemischt', '2026-09-29', false, true, null),
  (6066, 6, 17, null, 'Asylverfahren möglichst außerhalb der EU in sicheren Drittstaaten', '{601,605}', 6106, 1, 1, null, 'Asylverfahren außerhalb der EU sollen die Weiterreise nach Europa unattraktiv machen; belegt ist das nicht, bisherige Modelle (Großbritannien–Ruanda, Italien–Albanien) kamen kaum in Gang. Umsetzbar nur mit EU-Regeln und aufnahmebereiten Drittstaaten.', 'https://bsw-vg.de/wp-content/themes/bsw/assets/downloads/BSW%20Wahlprogramm%202025.pdf#page=38', null, 'offen', '2026-09-29', false, true, null),
  (6123, 6, 11, 'ST', 'Bezahlkarte für Asylsuchende dauerhaft beibehalten und weiterentwickeln', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true, null),
  (6124, 6, 11, 'ST', 'Zentrale Erstaufnahme dauerhaft absichern', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true, null),
  (6125, 6, 11, 'ST', 'Leistungsfähige Ausländerbehörden absichern und weiterentwickeln', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'offen', '2026-09-29', false, true, null),
  (6126, 6, 11, 'ST', 'Auf Bundesebene: Asylverfahren an den EU-Außengrenzen, Aufnahmeprogramme beenden, Familiennachzug zu subsidiär Schutzberechtigten weiter aussetzen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://www.cdulsa.de/sites/www.cdulsa.de/files/downloads/regierungsprogramm_ltw_web.pdf#page=8', null, 'gemischt', '2026-09-29', false, true, null),
  (6127, 6, 12, 'ST', 'Kommunen für die Erstintegration ausstatten', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://spdsachsenanhalt.de/wp-content/uploads/sites/63/2026/03/SPD-Wahlprogramm-2026.pdf#page=11', null, 'gemischt', '2026-09-29', false, true, null),
  (6128, 6, 13, 'ST', 'Ausländerbehörden besser ausstatten und zu Migrationszentren weiterentwickeln', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=78', null, 'offen', '2026-09-29', false, true, null),
  (6129, 6, 13, 'ST', 'Geflüchtete zügig in private Wohnungen vermitteln', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://www.gruene-lsa.de/wp-content/uploads/2026/05/Programm-zur-Landtagswahl-2026.pdf#page=78', null, 'gemischt', '2026-09-29', false, true, null),
  (6130, 6, 14, 'ST', 'Ausländerbehörden bei der Digitalisierung unterstützen; Arbeitserlaubnis binnen vier Wochen', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.fdp-lsa.de/sites/default/files/2026-07/fdpwahlprogrammltw2026.pdf#page=10', null, 'offen', '2026-09-29', false, true, null),
  (6131, 6, 15, 'ST', 'Über den Bundesrat stärkere Grenzkontrollen und Zurückweisungen durchsetzen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=27', null, 'gemischt', '2026-09-29', false, true, null),
  (6132, 6, 15, 'ST', 'Aufnahme von Personen verweigern, die aus einem sicheren Drittstaat eingereist sind', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=27', null, 'offen', '2026-09-29', false, true, null),
  (6133, 6, 15, 'ST', 'Aufnahmestopp des Landes als Ultima Ratio', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=31', null, 'offen', '2026-09-29', false, true, null),
  (6134, 6, 15, 'ST', 'Zuzugsstopps für überforderte Kommunen verhängen (negative Wohnsitzauflage)', '{601}', 6119, 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=30', null, 'gemischt', '2026-09-29', false, true, null),
  (6135, 6, 15, 'ST', 'Asylbewerber in zentralen Unterkünften unterbringen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=33', null, 'offen', '2026-09-29', false, true, null),
  (6136, 6, 15, 'ST', 'Sachleistungsprinzip konsequent anwenden', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://afd-lsa.de/wp-content/uploads/2026/07/AfD_Sachsen-Anhalt_Regierungsprogramm_2026_230726-web.pdf#page=35', null, 'offen', '2026-09-29', false, true, null),
  (6137, 6, 16, 'ST', 'Aufnahmegesetz reformieren; Integrationsbudget mit Mitteln für die Kommunen', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://www.dielinke-sachsen-anhalt.de/fileadmin/aaa_download_lsa/Parteitage/10._LPT_2._Tagung_VV_LTW_2026/Beschluesse/2026-03-19_Landtagswahlprogramm__final_.pdf#page=97', null, 'gemischt', '2026-09-29', false, true, null),
  (6138, 6, 17, 'ST', 'Unterbringungskosten der Kommunen durch den Bund übernehmen lassen', '{601}', 6122, 1, 1, null, 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'https://st.bsw-vg.de/wp-content/uploads/2026/04/BSW_Landtagswahlprogramm_SachsenAnhalt.pdf#page=65', null, 'gemischt', '2026-09-29', false, true, null),
  (6139, 6, 11, 'MV', 'Missbrauch der Bezahlkarte beenden', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://cdu-mv.de/wp-content/uploads/2026/06/Wahlprogramm-CDU-MV-2026.pdf#page=37', null, 'offen', '2026-09-29', false, true, null),
  (6140, 6, 13, 'MV', 'Gemeinschaftsunterkünfte reduzieren, dezentrales Wohnen stärken', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://gruene-mv.de/?wpdmdl=33772#page=92', null, 'gemischt', '2026-09-29', false, true, null),
  (6141, 6, 14, 'MV', 'Menschen ohne Bleibeperspektive in den Erstaufnahmeeinrichtungen belassen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=144', null, 'offen', '2026-09-29', false, true, null),
  (6142, 6, 14, 'MV', 'Landesweit einheitliche Bezahlkarte umsetzen und beibehalten', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=143', null, 'offen', '2026-09-29', false, true, null),
  (6143, 6, 14, 'MV', 'Ausländerbehörden personell und organisatorisch stärken', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://www.fdp-mv.de/sites/default/files/2026-06/Landtagswahlprogramm_2026.pdf#page=144', null, 'offen', '2026-09-29', false, true, null),
  (6144, 6, 15, 'MV', 'Landesweiten Aufnahmestopp als Option', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=48', null, 'offen', '2026-09-29', false, true, null),
  (6145, 6, 15, 'MV', 'Den Bund zu echtem Grenzschutz drängen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=48', null, 'gemischt', '2026-09-29', false, true, null),
  (6146, 6, 15, 'MV', 'Asylbewerber in wenigen großen Unterkünften unterbringen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=49', null, 'offen', '2026-09-29', false, true, null),
  (6147, 6, 15, 'MV', 'Sachleistungsprinzip maximal ausweiten', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://afd-vg.de/wp-content/uploads/2026/06/AfD-Regierungsprogramm-Mecklenburg-Vorpommern-2026.pdf#page=52', null, 'offen', '2026-09-29', false, true, null),
  (6148, 6, 16, 'MV', 'Dezentrale Unterbringung priorisieren; Kommunen bei der Wohnraumversorgung Geflüchteter unterstützen', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://wahlprogramm26.die-linke-mv.de/wp-content/uploads/sites/77/2026/08/LINKE-MV_LTW26_Langwahlprogramm_A4_web.pdf#page=13', null, 'gemischt', '2026-09-29', false, true, null),
  (6149, 6, 17, 'MV', 'Geflüchtete nach der tatsächlichen Leistungsfähigkeit der Kommunen verteilen', '{601}', 6119, 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=74', null, 'gemischt', '2026-09-29', false, true, null),
  (6150, 6, 17, 'MV', 'Unterbringung verlässlich durch Land und Bund finanzieren', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=74', null, 'gemischt', '2026-09-29', false, true, null),
  (6151, 6, 17, 'MV', 'Asylverfahren an den EU-Außengrenzen oder in sicheren Drittstaaten unterstützen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://mv.bsw-vg.de/wp-content/uploads/2026/04/Landeswahlprogramm-2026.pdf#page=73', null, 'gemischt', '2026-09-29', false, true, null),
  (6152, 6, 11, 'BE', 'Asylbewerber vom ersten Tag bis zur Entscheidung über den Asylantrag in zentralen Einrichtungen unterbringen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=25', null, 'offen', '2026-09-29', false, true, null),
  (6153, 6, 11, 'BE', 'Bezahlkarte dauerhaft etablieren', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://berlin-wird.de/image/uploads/data/regierungsprogramm2026_2031.pdf#page=25', null, 'offen', '2026-09-29', false, true, null),
  (6154, 6, 12, 'BE', 'Weg von Notunterkünften: dezentrales Wohnen, Geflüchtetenwohnen ausbauen, alle Bezirke beteiligen', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (6155, 6, 12, 'BE', 'Gemeinschaftspauschale je Geflüchteten und Bezirk stärken', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://library.fes.de/pdf-files/bibliothek/ltw-programme/SPD_Berlin_Wahlprogramm_20260521-v3-4_7942063.pdf#page=52', null, 'gemischt', '2026-09-29', false, true, null),
  (6156, 6, 13, 'BE', 'Unterbringung vorrangig in Wohnungen und kleineren Gemeinschaftsunterkünften in allen Bezirken', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=145', null, 'gemischt', '2026-09-29', false, true, null),
  (6157, 6, 13, 'BE', 'Jährliche Pauschale je Unterbringungsplatz für die Bezirke', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=72', null, 'gemischt', '2026-09-29', false, true, null),
  (6158, 6, 13, 'BE', 'Senatskommission Unterbringung soll neue Standorte zügig festlegen', '{601}', 6121, 2, 2, null, 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', null, 'gemischt', '2026-09-29', false, true, null),
  (6159, 6, 13, 'BE', 'Landesamt für Einwanderung stärken, digitales Antragssystem für alle Aufenthaltstitel', '{601}', 6115, 2, 2, null, 'Setzt direkt an der Überlastung der Ausländerbehörden an; wie viel schneller die Verfahren werden, hängt von Stellen und Digitalisierung ab und ist wenig untersucht. Das Land kann Personal und Digitalisierung mitfinanzieren, braucht dafür aber Geld und Fachkräfte.', 'https://gruene.berlin/fileadmin/BE/lv_berlin/files/Wahlprogramm_2026_Online.pdf#page=146', null, 'offen', '2026-09-29', false, true, null),
  (6160, 6, 14, 'BE', 'Bezahlkarte für Geflüchtete sofort einführen', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=96', null, 'offen', '2026-09-29', false, true, null),
  (6161, 6, 14, 'BE', 'Bei guter Bleibeprognose dezentrale Unterbringung in Wohnungen („Leverkusener Modell“)', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://www.fdp-berlin.de/sites/default/files/2026-07/Wahlprogramm_FDP%20Berlin_Abgeordnetenhauswahl%202026_FINAL.pdf#page=96', null, 'gemischt', '2026-09-29', false, true, null),
  (6162, 6, 15, 'BE', 'Sofortiger Aufnahmestopp für Asylbewerber in Berlin', '{601}', 6120, 1, 0, null, 'Ein Aufnahmestopp würde das Land entlasten, den Bedarf aber auf andere Länder verschieben. Die Länder sind nach dem Asylgesetz verpflichtet, die ihnen zugewiesenen Asylsuchenden aufzunehmen; ein einseitiger Stopp ist rechtlich derzeit nicht umsetzbar.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=22', null, 'offen', '2026-09-29', false, true, null),
  (6163, 6, 15, 'BE', 'Umstellung auf reine Sachleistungen', '{601}', 6113, 1, 3, null, 'Bezahlkarte und Sachleistungen sollen Anreize senken und Auszahlungen vereinfachen; eine Wirkung auf die Zahl der Neuankommenden ist nicht belegt, an Unterkünften und Ausländerbehörden ändert sich nichts. Die Länder können sie im Rahmen des Asylbewerberleistungsgesetzes selbst einführen.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=23', null, 'offen', '2026-09-29', false, true, null),
  (6164, 6, 15, 'BE', 'Freie Plätze in bestehenden Unterkünften voll belegen; zentrale Unterbringung von Personen mit geringen Anerkennungschancen', '{601}', 6114, 1, 2, null, 'Zentrale Unterbringung, etwa bis zum Asylbescheid, entlastet die Kommunen, verlagert den Bedarf an Plätzen aber auf das Land; ob Verfahren und Rückführungen dadurch schneller werden, ist kaum untersucht. Das Land schafft die Plätze, die Wohnpflicht regelt der Bund.', 'https://lichtenberg.afd.berlin/wp-content/uploads/2026/07/AfD-WK-Berlin-Wahlprogramm-Webversion.pdf#page=23', null, 'offen', '2026-09-29', false, true, null),
  (6165, 6, 16, 'BE', 'Bezirke verpflichten, Flächen für Gemeinschaftsunterkünfte bereitzustellen; leer stehende Gebäude aktivieren', '{601}', 6121, 2, 2, null, 'Verbindliche Vorgaben für Standorte und die Nutzung leer stehender Gebäude setzen direkt an fehlenden Unterkünften an; Planung und Umbau dauern aber, und gegen einzelne Standorte gibt es oft Widerstand vor Ort. Umsetzbar über Landesrecht und Landeshaushalt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true, null),
  (6166, 6, 16, 'BE', 'Mehr Geflüchtete über Kooperationsverträge mit landeseigenen Wohnungsbaugesellschaften in eigenen Wohnraum vermitteln', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true, null),
  (6167, 6, 16, 'BE', 'Infrastrukturprämien für die Bezirke je untergebrachter Person', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=283', null, 'gemischt', '2026-09-29', false, true, null),
  (6168, 6, 16, 'BE', 'Vom Bund eine Personenpauschale für die Unterbringungskosten fordern', '{601}', 6122, 1, 1, null, 'Eine volle Kostenübernahme durch den Bund würde Länder und Kommunen finanziell entlasten, schafft aber nicht sofort Plätze; ein Land kann sie nur fordern, entscheiden müssen Bundesregierung und Bundestag.', 'https://dielinke.berlin/fileadmin/download/2026/Wahlprogramm_AGH_2026_Die_Linke_Berlin.pdf#page=285', null, 'gemischt', '2026-09-29', false, true, null),
  (6169, 6, 17, 'BE', 'Grenzkontrollen und Zurückweisungen an den deutschen Grenzen unterstützen', '{601}', 6117, 1, 1, null, 'Grenzkontrollen, Zurückweisungen, Familiennachzug oder Asylverfahren an den EU-Außengrenzen kann ein Land nicht selbst regeln, sondern nur über den Bundesrat oder beim Bund darauf hinwirken; die Wirkung solcher Maßnahmen auf die Zugangszahlen ist zudem umstritten.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6170, 6, 17, 'BE', 'Asylbewerber stärker auf die umliegenden Bundesländer verteilen', '{601}', null, 1, 1, null, 'Eine andere Verteilung zwischen den Ländern würde Berlin entlasten, verschiebt den Bedarf aber nur; den Verteilschlüssel (Königsteiner Schlüssel) legen Bund und Länder gemeinsam fest, Berlin kann ihn nicht allein ändern.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'offen', '2026-09-29', false, true, null),
  (6171, 6, 17, 'BE', 'Bezirke, die bisher am meisten geleistet haben, bei der Verteilung entlasten', '{601}', 6119, 1, 3, null, 'Verteilung nach Leistungsfähigkeit oder Zuzugssperren für überlastete Orte (§ 12a Aufenthaltsgesetz) entlasten einzelne Kommunen, verschieben den Bedarf aber nur im Land; Wohnsitzauflagen können laut Studien die Arbeitsaufnahme verzögern. Das Land kann es selbst regeln.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (6172, 6, 17, 'BE', 'Ansiedlung mit einem Infrastrukturzuschuss für den Bezirk verbinden', '{601}', 6116, 1, 2, null, 'Mehr Landesgeld, etwa als Pauschale je Platz oder Person, setzt an der Kapazitätsseite an; Geld allein schafft aber nicht sofort Unterkünfte, Kitaplätze oder Personal, und die Programme nennen meist keinen Umfang. Umsetzbar über den Landeshaushalt.', 'https://bsw.berlin/wp-content/uploads/Wahlprogramm-BSW-Berlin-AGH-Wahl-2026.pdf#page=35', null, 'gemischt', '2026-09-29', false, true, null),
  (7995, 6, 14, null, 'Kein Anspruch auf Sozialleistungen für Personen, die Identitätsfeststellungsverfahren aktiv behindern', '{604}', null, 1, 2, null, 'Leistungskürzung bei Verweigerung der Mitwirkung kann Anreiz zur Identitätsklärung setzen; Wirkung auf Rückführungen ist kaum untersucht, die Hauptursache liegt oft bei Herkunftsstaaten. Das Existenzminimum begrenzt Kürzungen, Bundesgesetz möglich.', 'https://www.fdp.de/sites/default/files/2024-12/fdp-wahlprogramm_2025.pdf#page=28', null, 'offen', '2026-10-05', false, true, 'blind'),
  (7996, 6, 15, null, 'Asylantragstellung nur bei nachgewiesener Identität und Staatsangehörigkeit', '{604}', null, 1, 0, null, 'Identitätsklärung ist ein Hauptproblem bei Rückführungen, aber wer ohne Papiere flieht, könnte gar keinen Antrag mehr stellen; das widerspricht dem Zugang zum Asylverfahren (Grundgesetz, EU-Recht, Genfer Konvention). Wirkung auf Rückführungen kaum untersucht.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=104', null, 'offen', '2026-10-05', false, true, 'blind'),
  (7997, 6, 15, null, 'Asylrecht entfällt bei Falschangaben zur Identität im Asylverfahren', '{604}', null, 1, 1, null, 'Sanktion für Täuschung kann Anreize zu korrekten Angaben setzen, klärt aber keine Identität und löst nicht das Papierproblem. Der Wegfall des Asylrechts berührt Art. 16a GG und Flüchtlingsschutz nach EU-Recht; nur mit großen Hürden.', 'https://www.afd.de/wp-content/uploads/2025/02/AfD_Bundestagswahlprogramm2025_web.pdf#page=105', null, 'offen', '2026-10-05', false, true, 'blind'),
  (8490, 6, 18, null, 'Spezialisierte Kammern an den Verwaltungsgerichten für Asylprozesse, um Verfahren zu beschleunigen', '{602}', null, 1, 2, null, 'Spezialisierte Asylkammern können Verfahren beschleunigen (NRW meldet kürzere Dauer, zusammen mit mehr Personal); § 83 AsylG sieht sie aber schon vor, viele Gerichte haben sie. Einrichtung und Richterstellen liegen bei den Ländern.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=136', null, 'offen', '2026-10-07', false, true, 'blind'),
  (8491, 6, 18, null, 'Bundesweite kostenlose Asylberatung zur Begleitung der Asylsuchenden und Beschleunigung der Verfahren', '{602}', null, 1, 3, null, 'Beratung kann Anhörungen vorbereiten und Fehlentscheidungen vermeiden; die BAMF-Evaluation 2026 konnte eine Wirkung auf Verfahrensdauer und Klagen mangels Daten nicht messen. Der Bund fördert die Beratung seit 2023 (§ 12a AsylG).', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=136', 'https://www.asyl.net/view/evaluation-der-behoerdenunabhaengigen-asylverfahrensberatung', 'offen', '2026-10-07', false, true, 'blind'),
  (8492, 6, 18, null, 'Arbeitserlaubnis vom ersten Tag an, unabhängig vom Aufenthaltsstatus und vom einzelnen Arbeitgeber', '{603}', 6110, 2, 3, null, 'Ein früher Zugang zum Arbeitsmarkt setzt direkt an; Studien zeigen, dass Beschäftigungsverbote die Integration in Arbeit noch Jahre später verzögern. Sprachkurse und Anerkennung bleiben davon unberührt. Per Bundesgesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=51', null, 'belegt', '2026-10-07', false, true, null),
  (8493, 6, 18, null, 'Abschlüsse werden nach Gleichwertigkeit des Berufsbildes im Ausbildungsland anerkannt statt individuell geprüft', '{603}', 6101, 2, 2, null, 'Einfachere und schnellere Anerkennungsverfahren setzen an einer Hürde an, die das IAB nennt; wie viel schneller es wird, hängt von der Ausgestaltung ab. Für viele reglementierte Berufe sind die Länder zuständig.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=51', null, 'gemischt', '2026-10-07', false, true, null),
  (8494, 6, 18, null, 'Kostenlose Deutschkurse für alle Zielgruppen unabhängig vom Aufenthaltsstatus', '{603}', 6107, 2, 3, null, 'Mehr und früher zugängliche Sprach- und Integrationskurse verkürzen Wartezeiten; Studien des IAB zeigen, dass Integrationskurse Sprachkenntnisse und Beschäftigung verbessern. Anerkennung und Arbeitsmarktzugang bleiben davon unberührt. Der Bund finanziert die Kurse bereits.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=138', null, 'belegt', '2026-10-07', false, true, null),
  (8495, 6, 18, null, 'Dublin-Verordnung abschaffen und Asylsuchende nach BIP, Bevölkerungsdichte und Größe auf die Länder verteilen', '{605}', 6109, 1, 1, null, 'Eine verbindliche Verteilung in der EU würde die Zuständigkeitsfrage anders lösen; ob Asylsuchende dann im zugewiesenen Staat bleiben, ist offen. Umsetzbar nur mit einer Mehrheit der EU-Staaten, die bisher nicht in Sicht ist.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=135', null, 'offen', '2026-10-07', false, true, null),
  (8496, 6, 18, null, 'Chancenjahr: Menschen mit abgelehntem Asylantrag können sich durch ein Jahr Arbeit einen Aufenthaltstitel erarbeiten', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=138', null, 'belegt', '2026-10-07', false, true, null),
  (8497, 6, 18, null, 'Dauerhafter Aufenthaltsstatus, wenn eine Abschiebung drei Jahre lang nicht vollzogen wurde und Integrationsbereitschaft gezeigt wurde', '{606}', 6108, 2, 3, null, 'Ein Bleiberecht für gut integrierte Geduldete beendet die Kettenduldung direkt; mit dem Chancen-Aufenthaltsrecht von 2022 haben viele Geduldete einen Aufenthaltstitel bekommen. Wer die Bedingungen nicht erfüllt, bleibt geduldet. Per Bundesgesetz umsetzbar.', 'https://voltdeutschland.org/storage/assets-btw25/volt-programm-bundestagswahl-2025.pdf#page=139', null, 'belegt', '2026-10-07', false, true, null),
  (8602, 6, 18, 'BE', 'Einheitlicher Rahmenvertrag mit Qualitätskriterien und verlässlicher Refinanzierung für Anbieter, die den Bezirken Unterbringungsplätze bereitstellen.', '{601}', null, 1, 3, null, 'Ein Rahmenvertrag mit verlässlicher Refinanzierung macht die Bereitstellung von Plätzen planbarer und kann teure Notbeschaffung vermeiden; zusätzliche Plätze schafft er nicht direkt, und höhere Qualitätsvorgaben können Kosten erhöhen. Das Land kann ihn selbst regeln.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=107', 'https://www.bpb.de/themen/migration-integration/kurzdossiers/kommunale-migrations-und-fluechtlingspolitik/577376/kommunale-unterbringung-von-gefluechteten-in-deutschland/', 'offen', '2026-10-08', false, true, 'blind'),
  (8603, 6, 18, 'BE', 'Feste Stellen für die Belange Zugewanderter in Ämtern, darunter Landesamt für Einwanderung und Landesamt für Flüchtlingsangelegenheiten.', '{601}', null, 1, 2, null, 'Zusätzliche feste Stellen, auch in Einwanderungs- und Flüchtlingsbehörden, können Anliegen bündeln und Behörden etwas entlasten; die Überlastung entsteht laut Studien aber auch durch komplexes Recht und schleppende Digitalisierung, und Zahl und Wirkung der Stellen bleiben offen.', 'https://voltdeutschland.org/storage/assets-berlin/pdf/policy-wahlprogramm-2026/wahlprogramm-(last_edited_5-8-2026).pdf#page=105', 'https://www.bertelsmann-stiftung.de/de/unsere-projekte/migration-fair-gestalten/projektnachrichten/studie-auslaenderbehoerden-zwischen-anspruch-und-alltag', 'offen', '2026-10-08', false, true, 'blind'),
  (8604, 6, 18, 'ST', 'Geflüchtete dezentral statt in großen Sammelunterkünften unterbringen, um Kosten zu senken und Teilhabe früh zu ermöglichen.', '{601}', 6118, 1, 2, null, 'Wohnungen statt Sammelunterkünften erleichtern das Ankommen und können günstiger sein; zusätzliche Plätze entstehen aber nur, wo Wohnungen frei sind, in angespannten Wohnungsmärkten konkurriert der Bedarf mit anderen Wohnungssuchenden. Das Land kann es über Aufnahmegesetz und Förderung steuern.', 'https://voltdeutschland.org/storage/assets-sachsen-anhalt/pdf/landtagswahl-2026/wahlprogramm_volt_lv_lsa.pdf#page=135', null, 'gemischt', '2026-10-08', false, true, null);

